import { approvalCheckpointSchema, gateLogAppendSchema, getAgentSchema, getCommandSchema, getRuleSchema, getSkillSchema, harnessDetectSchema, harnessScaffoldSchema, healthSchema, projectContextSchema, listAgentsSchema, listCommandsSchema, listRulesSchema, listSkillsSchema, listWorkflowTypesSchema, paperclipIssueCheckoutSchema, paperclipIssueCommentSchema, paperclipIssueUpdateSchema, reportUsageSchema, suggestModelTierSchema, workflowConfirmSchema, workflowHandoffAppendSchema, workflowHandoffReadSchema, workflowStateLoadSchema, workflowStateSaveSchema, workflowRunQuerySchema, workflowStepSchema, workflowUsageTotalsSchema, workflowVerifySchema, } from "./schemas-zod.js";
import { typeboxSchemas, PN_CORE_TOOL_NAMES } from "./schemas-typebox.js";
import { handleApprovalCheckpoint, handleGateLogAppend, handleGetAgent, handleGetCommand, handleGetRule, handleGetSkill, handleHarnessDetect, handleHarnessScaffold, handleHealth, handleProjectContext, handleListAgents, handleListCommands, handleListRules, handleListSkills, handleListWorkflowTypes, handlePaperclipIssueCheckout, handlePaperclipIssueComment, handlePaperclipIssueUpdate, handleReportUsage, handleSuggestModelTier, handleWorkflowConfirm, handleWorkflowHandoffAppend, handleWorkflowHandoffRead, handleWorkflowStateLoad, handleWorkflowStateSave, handleWorkflowRunQuery, handleWorkflowStep, handleWorkflowUsageTotals, handleWorkflowVerify, } from "./handlers.js";
function def(name, label, description, zodSchema, annotations, 
// eslint-disable-next-line @typescript-eslint/no-explicit-any
handler) {
    const typeboxParameters = typeboxSchemas[name];
    if (!typeboxParameters) {
        throw new Error(`pn-core-mcp: missing TypeBox schema for tool ${name}`);
    }
    return {
        name,
        label,
        description,
        zodSchema,
        typeboxParameters,
        annotations,
        handler: handler,
    };
}
const readOnly = { readOnlyHint: true, destructiveHint: false, idempotentHint: true };
const write = { readOnlyHint: false, destructiveHint: false, idempotentHint: false };
const destructive = { readOnlyHint: false, destructiveHint: true, idempotentHint: false };
export const PN_CORE_TOOLS = [
    def("health", "Health", "Lightweight health check. Returns status, version, server calendar date (UTC), ISO timestamp, and capability summary. Call before dating changelogs, copyright years, or 'as of' lines when you need the MCP host clock.", healthSchema, readOnly, handleHealth),
    def("project_context", "Project Context", "Cold-session project context packet (MCP pull). Both modes include compact responseAliases (scr/eli/foc/ref/scp), active_run (state path + source, selected run_id, last served vs completed step, step_status, resume) and consistency (mismatches between state file, run log, handoff log, and last save; ok=false means no run is silently selected — pass run_id or state_path). drift covers context-index files only (drift_scope). mode=operator returns counts and drift; mode=agent (default) also lists context-index artifacts with attested derived status and recent workflow-handoff / run-events trail. Call at session start when pn-core MCP is available.", projectContextSchema, readOnly, handleProjectContext),
    def("list_workflow_types", "List Workflow Types", "List available workflow types and their step counts. Use for discoverability before calling workflow_step.", listWorkflowTypesSchema, readOnly, handleListWorkflowTypes),
    def("harness_detect", "Harness Detect", "Detect which agent harness (cursor | claude_code | codex | pi) this session runs in and return the per-harness file layout: instructions file, rules dir + format, skills dir, commands dir, agents dir, MCP config path, hooks. Precedence: PNCORE_HARNESS env > process env signals > workspace folders. Call before writing project-context, rules, or skills so files land only where the active harness reads them.", harnessDetectSchema, readOnly, handleHarnessDetect),
    def("harness_scaffold", "Harness Scaffold", "Write pnCore onboarding files for the selected harnesses only (default: detected). project_context → .cursor/rules/*.mdc (Cursor), .claude/rules/*.md (Claude Code), or a managed block in AGENTS.md (Codex, Pi); project_skill → the harness skills dir (.cursor/skills, .claude/skills, .agents/skills); no_trailers_rule → rule file where a rules dir exists; mcp_config (opt-in) → .cursor/mcp.json, .mcp.json, .codex/config.toml, or .pi/settings.json packages. dryRun returns the plan with contents; existing files are skipped unless overwrite. Paths are workspace-contained (process cwd).", harnessScaffoldSchema, write, handleHarnessScaffold),
    def("suggest_model_tier", "Suggest Model Tier", "Return the suggested LLM model tier for a workflow step or subagent role. Omit `step` to get the full per-step table for the workflow. When `role` is set (explorer | builder | judge | checker | orchestrator), returns the tier for that subagent kind and ignores step. Tiers: fast | standard | premium | premium_thinking | long_horizon. Suggestions reflect cognitive demand and incorporate modelTierOverrides / tierAliases from features.json or PNCORE_FEATURES.", suggestModelTierSchema, readOnly, handleSuggestModelTier),
    def("list_skills", "List Skills", "List pnCore skills. Without filters returns a category index with counts; use category or filter to drill in.", listSkillsSchema, readOnly, handleListSkills),
    def("get_skill", "Get Skill", "Return full markdown content of a skill by id (e.g. pn-discovery-questionnaire, pn-svg-creator).", getSkillSchema, readOnly, handleGetSkill),
    def("list_agents", "List Agents", "List pnCore agent ids and descriptions. Use include='all' to surface internal orchestration agents.", listAgentsSchema, readOnly, handleListAgents),
    def("get_agent", "Get Agent", "Return full markdown content of an agent by id (e.g. pn-project-builder, pn-skeptic).", getAgentSchema, readOnly, handleGetAgent),
    def("list_commands", "List Commands", "List all pnCore command ids and descriptions.", listCommandsSchema, readOnly, handleListCommands),
    def("get_command", "Get Command", "Return full markdown content of a command by id (e.g. pn-build, pn-new, pn-design, pn-svg-creator).", getCommandSchema, readOnly, handleGetCommand),
    def("list_rules", "List Rules", "List all pnCore rule ids and descriptions.", listRulesSchema, readOnly, handleListRules),
    def("get_rule", "Get Rule", "Return full markdown content of a rule by id.", getRuleSchema, readOnly, handleGetRule),
    def("workflow_step", "Workflow Step", "Get the next instruction for a workflow step. Call this at workflow start and after completing each step. The tool validates state and returns a single instruction. Control flow is deterministic; the model cannot advance without valid state. Stateless: you supply full state on each call. When PNCORE_REQUIRE_APPROVAL_FOR_WORKFLOWS lists this workflowType and the step gate is human, state must include pncoreHumanGateTicket from approval_checkpoint (see MCP README).", workflowStepSchema, write, handleWorkflowStep),
    def("report_usage", "Report Usage", "Report token and cost usage for a workflow step. Call after workflow_step when the client has usage data. Optional path: append one JSON line to the file (e.g. .pncore/usage.jsonl in workspace). If path omitted, returns summary only.", reportUsageSchema, write, handleReportUsage),
    def("workflow_usage_totals", "Workflow Usage Totals", "Sum inputTokens, outputTokens, and optional costUsd for a workflow run_id from a usage JSONL file (same format as report_usage). Scans tail of file for safety.", workflowUsageTotalsSchema, readOnly, handleWorkflowUsageTotals),
    def("workflow_handoff_append", "Workflow Handoff Append", "Append a bounded workflow step summary to JSONL for cross-session handoff (same run_id as workflow_step).", workflowHandoffAppendSchema, write, handleWorkflowHandoffAppend),
    def("workflow_handoff_read", "Workflow Handoff Read", "Read recent handoff lines for a run_id (workflow_handoff_append). New chat: call with run_id to restore context.", workflowHandoffReadSchema, readOnly, handleWorkflowHandoffRead),
    def("workflow_confirm", "Workflow Confirm", "Present a structured confirmation gate to the user. Use when ask_question is unavailable (MCP-only), or after AskQuestion in Cursor to record gate_id in .pncore/gate-log.jsonl. Returns formatted prompt text, options, and gate_id. You MUST output the prompt to the user, list the options, and STOP. Do not proceed until the user replies. For skeptic gates: set gate_type=skeptic, verdict, and non-empty context when verdict=revise.", workflowConfirmSchema, write, handleWorkflowConfirm),
    def("approval_checkpoint", "Approval Checkpoint", "Hard approval gate: returns success only if approval_token equals PNCORE_APPROVAL_TOKEN on the MCP server process. Configure the env var in MCP server config (not in chat). Optional workflow_type + workflow_step: when both are set and the token matches, appends a one-time ticket and returns pncoreHumanGateTicket for the next workflow_step human gate (used with PNCORE_REQUIRE_APPROVAL_FOR_WORKFLOWS). If the env var is unset, returns an error (fail closed).", approvalCheckpointSchema, write, handleApprovalCheckpoint),
    def("gate_log_append", "Gate Log Append", "Append-only audit line for human or workflow gates. Writes one JSON object per line (JSONL) under the workspace, same path rules as report_usage. Use after user outcomes at gates (complements approval_checkpoint).", gateLogAppendSchema, write, handleGateLogAppend),
    def("workflow_state_save", "Workflow State Save", "Save workflow state atomically (resume after disconnect). Path: path > PNCORE_STATE_PATH > .pncore/workflow-state.json, inside the workspace. Commit mode (run_id + step + summary, optional expected_revision): one call appends the handoff line and commits the state under revision N+1, refuses stale revisions (REVISION_CONFLICT), another run's file unless overwrite_run (RUN_MISMATCH), or a concurrent save (LOCKED), and returns revision + hashes read back from disk. Plain mode (state only) writes the file under the same lock without a revision.", workflowStateSaveSchema, { readOnlyHint: false, destructiveHint: false, idempotentHint: false }, handleWorkflowStateSave),
    def("workflow_state_load", "Workflow State Load", "Load workflow state from a file (e.g. after reconnect). Same path resolution as workflow_state_save. Returns { state, meta, path }: state without the persistence envelope (pass it to workflow_step), meta = { revision, run_id, step, savedAt, stateHash } from commit mode or null.", workflowStateLoadSchema, readOnly, handleWorkflowStateLoad),
    def("workflow_verify", "Workflow Verify", "Run a catalog (or policy-checked) verify command with no shell. Returns a GateReport with failureClass (none | missing_input | infrastructure | behavioral); exitCode !== 0 is a completed verify, not a tool error, and failureClass never changes a gate. inputs / env_required are checked immediately before spawn; a failed check records a preflight event and launches nothing. preflight_only runs just the checks (no disposeVerify needed). Spawning requires disposeVerify; fail-closed without a jail unless PNCORE_VERIFY_SANDBOX=restricted or Vitest test backend.", workflowVerifySchema, write, handleWorkflowVerify),
    def("workflow_run_query", "Workflow Run Query", "Query one run_id across the .pncore trails: verify attestations and acceptance (run-events.jsonl, default), plus kinds preflight (workflow_verify checks), step (workflow_step spans: stepIndex, sinceLastStepMs, engineMs, routing), load (get_* loads), usage, handoff, gate. timeline: true joins them into a per-step view with totals and the slowest step — answers where a run spent its time.", workflowRunQuerySchema, readOnly, handleWorkflowRunQuery),
    def("paperclip_issue_checkout", "Paperclip Issue Checkout", "Check out a Paperclip issue (POST /api/issues/:id/checkout). Use before starting work per pn-paperclip governance. Requires PAPERCLIP_API_URL, PAPERCLIP_API_KEY. issueId optional if PAPERCLIP_ISSUE_ID is set.", paperclipIssueCheckoutSchema, write, handlePaperclipIssueCheckout),
    def("paperclip_issue_comment", "Paperclip Issue Comment", "Add a markdown comment on a Paperclip issue (POST /api/issues/:id/comments with body). Requires PAPERCLIP_API_URL, PAPERCLIP_API_KEY. issueId optional if PAPERCLIP_ISSUE_ID is set.", paperclipIssueCommentSchema, destructive, handlePaperclipIssueComment),
    def("paperclip_issue_update", "Paperclip Issue Update", "Update a Paperclip issue status (PATCH /api/issues/:id). Prefer paperclip_issue_checkout for in_progress per governance. Requires PAPERCLIP_API_URL, PAPERCLIP_API_KEY. issueId optional if PAPERCLIP_ISSUE_ID is set.", paperclipIssueUpdateSchema, destructive, handlePaperclipIssueUpdate),
];
if (PN_CORE_TOOLS.length !== PN_CORE_TOOL_NAMES.length) {
    throw new Error(`pn-core-mcp: tool registry count mismatch (${PN_CORE_TOOLS.length} vs ${PN_CORE_TOOL_NAMES.length})`);
}
export { PN_CORE_TOOL_NAMES };
